CREATE SCHEMA IF NOT EXISTS org;
COMMENT ON SCHEMA org IS 'Organisation & Calendar: Institutions (schools, colleges, campuses), their departments, academic years and terms.';

CREATE TABLE org.institution (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    parent_institution_id uuid,
    code varchar(30) NOT NULL,
    name varchar(200) NOT NULL,
    slug varchar(200),
    institution_type varchar(30) NOT NULL DEFAULT  'school',
    email varchar(320),
    phone varchar(20),
    address_line1 varchar(255),
    address_line2 varchar(255),
    city_id uuid,
    state_province_id uuid,
    country_id uuid,
    postal_code varchar(12),
    timezone varchar(64),
    currency_id uuid,
    logo_file_id uuid,
    signature_file_id uuid,
    accreditation text,
    approval_authority text,
    status varchar(30) NOT NULL DEFAULT  'active',
    institution_type_id uuid,
    theme_id uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_institution PRIMARY KEY (id),
    CONSTRAINT ck_institution_institution_type CHECK (institution_type IN ('school', 'college', 'university', 'coaching_centre', 'training_centre')),
    CONSTRAINT ck_institution_status CHECK (status IN ('active', 'inactive')),
    CONSTRAINT uq_institution_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE org.institution IS 'A school, college, campus or training centre operated by a tenant. Institutions can be nested (group → campus).';
COMMENT ON COLUMN org.institution.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN org.institution.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN org.institution.parent_institution_id IS 'Parent institution for multi-campus groups.';
COMMENT ON COLUMN org.institution.code IS 'Institution code, unique within the tenant.';
