COMMENT ON COLUMN org.institution.status IS 'Institution state.';
COMMENT ON COLUMN org.institution.institution_type_id IS 'Configurable unit type (drives which attributes are captured).';
COMMENT ON COLUMN org.institution.theme_id IS 'Visual theme of the institution''s portal and apps.';
