CREATE UNIQUE INDEX uq_institution_2 ON org.institution (tenant_id, slug) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_institution_attribute_1 ON org.institution_attribute (institution_id, attr_key) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_institution_type_1 ON org.institution_type (tenant_id, name) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_institution_type_attribute_1 ON org.institution_type_attribute (institution_type_id, attribute_definition_id) WHERE deleted_at IS NULL;

